    for char in reversed(s):
        value = roman[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def shipping_cost(kg: float) -> float:
    if kg <= 1:
        return 5.0
    return 5.0 + 2.0 * int(kg)

